import java.util.ArrayList;
import java.util.List;

public class Ex02DynamicForeach {

    // 复刻 <foreach open="(" close=")" separator=",">
    static String placeholders(int n, String open, String close, String separator) {
        List<String> ph = new ArrayList<String>();
        for (int i = 0; i < n; i++) {
            ph.add("?");
        }
        return open + String.join(separator, ph) + close;
    }

    // 复刻 <foreach> 对变量的展开：每行一对占位符
    static String rowPlaceholders(int itemArity) {
        List<String> row = new ArrayList<String>();
        for (int i = 0; i < itemArity; i++) {
            row.add("?");
        }
        return "(" + String.join(", ", row) + ")";
    }

    static boolean plausibleSql(String sql) {
        return !sql.contains("()") && !sql.contains("( )");
    }

    public static void main(String[] args) {
        List<Integer> ids = new ArrayList<Integer>();
        ids.add(1);
        ids.add(2);
        ids.add(3);

        String inClause = placeholders(ids.size(), "(", ")", ",");
        System.out.println("ids             : " + ids);
        System.out.println("foreach IN      : SELECT * FROM t_user WHERE id IN " + inClause);
        System.out.println("bound params    : " + ids);
        System.out.println("in clause ok    : " + plausibleSql(inClause));

        List<Integer> empty = new ArrayList<Integer>();
        String emptyClause = placeholders(empty.size(), "(", ")", ",");
        System.out.println("empty IN        : SELECT * FROM t_user WHERE id IN " + emptyClause);
        System.out.println("empty in ok     : " + plausibleSql(emptyClause));

        List<String> batch = new ArrayList<String>();
        batch.add(rowPlaceholders(2));
        batch.add(rowPlaceholders(2));
        System.out.println("batch insert    : INSERT INTO t_user(name, age) VALUES " + String.join(", ", batch));
        System.out.println("batch params    : [tom, 20, amy, 30]");

        System.out.println("custom sep      : " + placeholders(2, "(", ")", " OR "));
    }
}
